const text = $input.first().json.output[0].content[0].text;

const article = JSON.parse(text);

article.content += `
<h2>🤖 About This Guide</h2>

<p>This guide was created using a custom AI-powered automation workflow built with <strong>n8n</strong>, <strong>OpenAI</strong> and <strong>WordPress</strong>.</p>

<p>The system automatically researches, writes, formats and publishes objective software tool reviews while maintaining a consistent structure, editorial quality and SEO best practices.</p>

<p><a href="https://YOUR-WORDPRESS-SITE.example/projects/building-a-scalable-tool-library-with-ai-and-n8n/" target="_blank" rel="noopener noreferrer">See how I built the workflow – Building a Scalable Tool Library with AI and n8n</a></p>

<p><a href="https://www.linkedin.com/" target="_blank" rel="noopener noreferrer">Connect with me on LinkedIn</a></p>
`;

return [
  {
    json: article
  }
];

const item = $input.first().json;

const imageHtml = `
<figure class="wp-block-image size-large">
  <img src="${item.guid.rendered}" alt="${item.primary_keyword}" />
</figure>
`;

let count = 0;

item.content = item.content.replace(/<\/p>/g, (match) => {
  count++;

  if (count === 2) {
    return `</p>\n${imageHtml}`;
  }

  return match;
});

return [
  {
    json: item
  }
];
